local _, WFJ = ...
WFJ.Data.add("book", {
  ["3845d43c27cb6359"] = { "vaga per ⟦Duskwood=Boscovespro⟧, divorato dal dolore per la perdita della moglie e dei figli e dall'odio verso se stesso. Mor'Ladim, come ora si fa chiamare, si aggira per ⟦Duskwood=Boscovespro⟧ con una vendetta e un odio ciechi, ed è noto per uccidere senza alcuna distinzione.", "." },
  ["38893c4061449206"] = { "I Titani conferirono potere a numerose razze perché li aiutassero a plasmare il mondo. Per scavare le insondabili caverne sotto la terra, i Titani crearono i terrigeni, simili a nani, dalla pietra magica e vivente. Per scavare i mari e sollevare la terra dal fondale, i Titani crearono gli immensi ma miti giganti marini. Per molte ere i Titani mossero e plasmarono la terra, finché non rimase un unico continente perfetto.", "." },
  ["389c234f7a1b2f52"] = { "Sebbene gli orchi prigionieri fossero tesi e smaniosi di tornare a combattere, i vari sorveglianti dei campi, di stanza nell'antica fortezza-prigione di Durnholde, mantennero la pace e una solida parvenza di ordine.", "." },
  ["38a7f556c8bea838"] = { "Kil'jaeden promise che, se Ner'zhul avesse portato a termine la sua oscura missione di spazzare via l'umanità dal mondo, sarebbe stato liberato dalla maledizione e avrebbe ricevuto un corpo nuovo e sano da abitare.", "." },
  ["38b66cc326989d02"] = { "Alcuni temono quelli come noi più dei draghi. Alcuni ci invidiano più dei fabbri più abili. Alcuni lodano la nostra forza in battaglia. Altri esaltano la nostra fede. E alcuni sono solo gelosi perché a bere li mandiamo sotto il tavolo! Ma sappi questo, {class}: sei tra i protettori più scelti di tutta Azeroth. La ⟦Holy Light=Luce Sacra⟧ ci dà forza tanto quanto noi la rafforziamo.\n\nTi dirò di più quando avrai preso un po' di confidenza con queste terre. Cercami dentro ⟦Anvilmar=Forgiamara⟧, sopra la Valle.\n\n-Bromos Grummner, istruttore dei paladini", "." },
  ["38bc97216e8372f5"] = { "Se volete riavere la renna viva, vi conviene pagare in fretta il riscatto. I Pirati dei Mari del Sud non vedono di buon occhio i ritardi nei pagamenti, e sappiamo quanto la bestia sia preziosa per la VOSTRA forma di pirateria.\n\nPortate la somma di 1000 monete d'oro all'imboccatura della ⟦Lost Rigger Cove=Cala del Sartiame⟧, a Tanaris. Qualsiasi tentativo di liberare la renna farà sì che Metzen faccia una lunghissima passeggiata giù da un'asse cortissima.\n\nArrr...\n\nI Pirati dei Mari del Sud", "." },
  ["38e078263643939c"] = { "I draghi si riunirono nella stratosfera, alti sopra ⟦Silithus=Silitus⟧: migliaia di piedi sopra la fortezza di ⟦Ahn'Qiraj=Ahn'qiraj⟧.\n\nC'era Anachronos, figlio di Nozdormu, Aspetto del Tempo.\n\nDal ⟦Emerald Dream=Sogno di Smeraldo⟧ giunse Merithra, figlia di Ysera, Aspetto della Natura.\n\nCaelestrasz, figlio di Alexstrasza, Aspetto della Vita, rappresentava lo Stormo dei Draghi Rossi.\n\nArygos, figlio di Malygos, Aspetto della Magia, rappresentava lo Stormo dei Draghi Blu.", "." },
})
